use std::cell::Ref;

pub(crate) fn received(&self) -> Option<Ref<'_, SpellCheckResults>> {
    Ref::filter_map(self.results.borrow(), |results| {
        results.as_ref().filter(|results| !results.suggestion_spans.is_empty())
    })
    .ok()
}

